const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const memphis = ee.Geometry.Point([-90.0490, 35.1495]);
  const roi = memphis.buffer(10000); // 10km radius around Memphis

  const date2021_start = '2021-09-01';
  const date2021_end = '2021-09-30';
  const date2023_start = '2023-09-01';
  const date2023_end = '2023-09-30';

  // 2. Data Acquisition using Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function addNDWI(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    return image.addBands(ndwi);
  }

  let col2021 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate(date2021_start, date2021_end)
    .map(maskClouds)
    .map(addNDWI);

  let col2023 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(roi)
    .filterDate(date2023_start, date2023_end)
    .map(maskClouds)
    .map(addNDWI);

  const size2021 = col2021.size().getInfo();
  const size2023 = col2023.size().getInfo();

  console.log(`2021 Images: ${size2021}`);
  console.log(`2023 Images: ${size2023}`);

  if (size2021 === 0 || size2023 === 0) {
    console.log('Trying Landsat 8/9 as fallback...');

    col2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date2021_start, date2021_end);

    col2023 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date2023_start, date2023_end);

    if (col2021.size().getInfo() === 0 || col2023.size().getInfo() === 0) {
      console.log('No data available for one or both periods.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Calculate water area
  const img2021 = col2021.median();
  const img2023 = col2023.median();

  const water2021 = img2021.select('NDWI').gt(0.2);
  const water2023 = img2023.select('NDWI').gt(0.2);

  // Check pixel counts
  const count2021 = water2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const count2023 = water2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`2021 Valid Pixels: ${count2021}`);
  console.log(`2023 Valid Pixels: ${count2023}`);

  if (count2021 === 0 || count2023 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Calculate water area
  const waterArea2021 = water2021.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const waterArea2023 = water2023.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`2021 Water Area: ${(waterArea2021 / 1e6).toFixed(2)} sq km`);
  console.log(`2023 Water Area: ${(waterArea2023 / 1e6).toFixed(2)} sq km`);

  // 5. Validation & Final Answer
  if (waterArea2021 === null || waterArea2023 === null || 
      waterArea2021 < 0 || waterArea2023 < 0) {
    console.log('Calculation failed or invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  const decrease = waterArea2023 < waterArea2021;
  console.log(`Width decreased: ${decrease}`);

  if (decrease) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
